// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    // the reference sends the whole balance back to msg.sender (this test contract);
    // it must be able to receive ETH or the transfer reverts
    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        // admissible domain: contract funded with at least 2 wei (wide range)
        amount = bound(amount, 2, 1e30);

        // owner of c is this test contract (it deployed c), so no prank needed
        vm.deal(address(c), amount);

        uint256 beforeC = address(c).balance;
        assertEq(beforeC, amount);
        uint256 beforeCaller = address(this).balance;

        c.withdrawAll();

        // general rule: after withdrawAll, the caller received EXACTLY the
        // entire prior balance of c (which is >= 2 wei)
        assertTrue(address(this).balance - beforeCaller == beforeC && address(c).balance == 0);
    }
}
